 Object.assign(data,{"Fried Calamari":["Todas","Cozinhe 1 lula, 1 farinha de trigo e 1 óleo; Jodi envia a receita ao atingir 3 corações."],"Apple":["Outono","A macieira leva 28 dias para amadurecer e produz no outono; maçãs também podem aparecer na caverna com morcegos frutíferos."],"Wood":["Todas","Corte árvores, galhos e troncos; Robin também vende madeira."],"Hardwood":["Todas","Corte tocos grandes, troncos grandes ou árvores de mogno com machado adequado."],"Woodskip":["Todas","Pesque no Bosque Secreto ou na Fazenda na Floresta, em qualquer horário e clima."],"Dinosaur Mayonnaise":["Todas","Processe um ovo de dinossauro na máquina de maionese."],"Void Mayonnaise":["Todas","Processe um ovo nulo na máquina de maionese."],"Mango":["Verão","A mangueira leva 28 dias para amadurecer; produz no verão no vale e o ano todo na Ilha Gengibre ou estufa."],"Honey":["Todas (Ilha Gengibre); primavera, verão e outono (vale)","A casa de abelhas produz mel a cada 4 dias, exceto no inverno no vale; na Ilha Gengibre produz o ano todo. Flores próximas podem alterar o tipo de mel."],"Melon":["Verão","Cultive sementes de melão: crescimento base de 12 dias."],"Vegetable Medley":["Todas","Cozinhe 1 tomate e 1 beterraba; Caroline envia a receita ao atingir 7 corações."],"Mussel":["Todas","Colete na praia ou use covo no oceano."],"Corn":["Verão e outono","Cultive sementes de milho: 14 dias até a primeira colheita e novas colheitas a cada 4 dias."],"Blueberry":["Verão","Cultive sementes de mirtilo: 13 dias até a primeira colheita e novas colheitas a cada 4 dias."],"Artichoke Dip":["Todas","Cozinhe 1 alcachofra e 1 leite; aprenda a receita na Rainha do Molho em 28 de outono do ano 1."],"Strawberry":["Primavera","Cultive sementes de morango: 8 dias até a primeira colheita e novas colheitas a cada 4 dias; compre sementes no Festival do Ovo."],"Morel":["Primavera","Colete na primavera no Bosque Secreto ou na Fazenda na Floresta; também pode aparecer na caverna com cogumelos e em tronco de cogumelos."],"Daffodil":["Primavera","Colete no vale durante a primavera."],"The Alleyway Buffet":["Todas","Procure na lixeira dourada escondida a leste da cidade; o livreiro pode vendê-lo por 20.000 ouros a partir do ano 3."],"Woody's Secret":["Todas","Derrube árvores: pode cair depois de mais de 20 árvores cortadas; o livreiro pode vendê-lo por 20.000 ouros a partir do ano 3."],"Obsidian":["Todas","Leve um omnigeodo ou geodo de magma ao ferreiro para abri-lo."],"Truffle Oil":["Todas","Coloque uma trufa na máquina de óleo."],"Tigerseye":["Todas","Leve um geodo de magma ou omnigeodo ao ferreiro para abri-lo."],"Omni Geode":["Todas","Encontre em rochas e em outras fontes durante a exploração; leve ao ferreiro para abri-lo."],"Oyster":["Todas","Colete na praia ou use covo no oceano."],"Sea Urchin":["Todas","Colete na praia, especialmente na área leste acessível após reparar a ponte."],"Ostrich Egg":["Todas","Obtenha de avestruzes, em baús raros do Vulcão ou escavando o local indicado pelo fragmento de diário 10 na Ilha Gengibre."],"ParrotEgg":["Todas","Após conquistar a Maestria de Combate, encontre este acessório em monstros, caixas ou barris nas minas, ou em salas de tesouro da Caverna da Caveira."],"Duck Egg":["Todas","Patos adultos no galinheiro produzem ovos de pata."],"FrogEgg":["Todas","Após conquistar a Maestria de Combate, encontre este acessório em monstros, caixas ou barris nas minas, ou em salas de tesouro da Caverna da Caveira."],"Fried Egg":["Todas","Cozinhe 1 ovo; a receita já é conhecida no início do jogo."],"Large Egg":["Todas","Galinhas felizes podem produzir ovos grandes; há variantes de casca branca e marrom."],"Void Egg":["Todas","Galinhas nulas produzem ovos nulos; um ovo inicial pode ser obtido pelo evento da bruxa ou comprado de Krobus."],"Pale Ale":["Todas","Coloque lúpulo em um barril para produzir pale ale."],"Pancakes":["Todas","Cozinhe 1 farinha de trigo e 1 ovo; a receita passa na Rainha do Molho em 14 de verão do ano 1 e também pode ser comprada no Saloon por 100 ouros."],"Maple Bar":["Todas","Cozinhe 1 xarope de ácer, 1 açúcar e 1 farinha de trigo; a receita passa na Rainha do Molho em 14 de verão do ano 2."],"Poppy":["Verão","Cultive sementes de papoula: crescimento base de 7 dias."],"Raisins":["Todas","Coloque cinco uvas no desidratador; ficam prontas na manhã seguinte."],"Rabbit's Foot":["Todas","Coelhos podem produzir um pé de coelho; serpentes da Caverna da Caveira também podem deixá-lo."]});
