(function(){
 const style=document.createElement('style');style.textContent=`.sprite-frame{position:relative;display:inline-flex;align-items:center;justify-content:center;flex:none;width:48px;height:48px;padding:6px;background:#f9d895;border:4px ridge #ae6e36;box-shadow:inset 0 0 0 2px #ffe9bb;border-radius:0}.sprite-frame .game-icon{border:0;padding:0;margin:0;width:32px;height:32px;background:transparent;box-sizing:border-box}.sprite-frame .quality-star{position:absolute;right:-5px;bottom:-5px;width:20px;height:20px;image-rendering:pixelated;border:0;background:transparent;padding:0;z-index:2}.item{gap:18px;border:2px solid #c9975d;background:#fff0cf}.item button{line-height:1.5}.bundle-star{display:none}.npc-card{display:flex;flex-direction:column;align-items:center;background:linear-gradient(#fce8bb,#fff7e2);border:4px ridge #b77940;border-radius:3px}.resident-frame{padding:7px;border:5px ridge #af7136;background:#edc17e;box-shadow:inset 0 0 0 2px #ffebbd}.resident-frame .portrait{width:96px;height:96px;margin:0;border:0;border-radius:0;padding:0}.hearts{display:flex;justify-content:center;flex-wrap:wrap;gap:3px;max-width:200px;margin:12px 0}.heart{width:14px;height:12px;image-rendering:pixelated}.heart.empty{opacity:.25;filter:grayscale(1)}.resident-name{margin:0 0 18px;padding:6px 20px;border:3px ridge #ad733c;background:#f3cf8b;box-shadow:0 3px 0 #7b4c2a55}.gift-list{width:100%;justify-content:center;gap:12px}.gift{flex-direction:column;min-width:100px;max-width:145px;padding:10px;gap:10px;border:2px solid #bb8d53;background:#fff4d7;line-height:1.4}.personal-gift{display:block;margin-top:6px;color:#65412c;background:#e5c68d;padding:3px 5px;border-radius:4px;font-size:10px}.dialog.item-modal{background:linear-gradient(135deg,#ffe9b8,#fff8e4);border:8px ridge #ae713c;border-radius:3px;box-shadow:0 0 0 3px #593c28,0 12px 40px #30200d77;color:#553822}.item-modal::backdrop{background:#242c1ecc}.item-modal .item-fields p{border:2px solid #cda66a;background:#fff9e9}.item-modal .item-details{padding:14px;border-bottom:3px double #b9894b;margin-bottom:15px}.item-modal h2{font-size:22px}#saveinfo{display:flex;flex-wrap:wrap;gap:14px;align-items:center;padding:12px;background:linear-gradient(#e8f0cc,#fff1ce);border:5px ridge #b27b43}#saveinfo h3,#saveinfo p{margin:0;padding:12px 16px;background:#fff3d5;border:3px ridge #c19256}#saveinfo h3{flex-basis:60%}.farmer-avatar{width:96px!important;height:160px!important;object-fit:contain;border:5px ridge #b48149;border-radius:0;padding:8px;background:linear-gradient(#cce3ac,#f2dc9a)}.pet-avatar{padding:8px;border:4px ridge #b48149;border-radius:0}.nav button,.card button{gap:15px}.nav button span{min-width:0}@media(max-width:600px){#saveinfo h3{flex-basis:100%}.gift{min-width:90px}.resident-frame .portrait{width:80px;height:80px}}`;document.head.append(style);
 const original=window.openItemPage;window.openItemPage=function(item){original(item);const modal=document.querySelector('#dialog');modal.dataset.category=item.category||'';const category=(item.category||'').toLowerCase();modal.style.background=/peix|fish/.test(category)?'linear-gradient(135deg,#d6edf1,#fff4d6)':/flor|flower|coleta|forag/.test(category)?'linear-gradient(135deg,#e1edca,#fff2ce)':/mineral|gema|gem/.test(category)?'linear-gradient(135deg,#e1d7ed,#fff2ce)':'linear-gradient(135deg,#ffe9b8,#fff8e4)';const title=document.querySelector('#dialogbody h2');if(title)modal.setAttribute('aria-label',item.name);if(item.quality){const tier={1:'silver',2:'gold',4:'iridium'}[item.quality];const source=window.guiaData?.visuals?.ui?.[tier];if(source){const img=document.createElement('img');img.src=source;img.alt='Qualidade '+({1:'prata',2:'ouro',4:'irídio'}[item.quality]);img.style.cssText='width:24px;height:24px;image-rendering:pixelated;border:0';document.querySelector('.item-details').append(img);}}};
})();
(function(){
 const style=document.createElement('style');style.textContent=`#dialog>button{display:flex;align-items:center;justify-content:center;margin:24px auto 4px;min-width:200px;min-height:52px;padding:12px 28px;border:4px ridge #ad7138;border-radius:3px;background:linear-gradient(#ffe5a7,#e4ba72);box-shadow:0 4px 0 #79502b;font-size:17px;font-weight:900;color:#57391f}#dialog>button:hover{background:#ffedbb}#dialog>button:focus-visible{outline:3px solid #315d94;outline-offset:5px}.item-details .game-icon{padding:8px;border:4px ridge #ad7138;background:#ffedc5;border-radius:0;box-sizing:content-box}.item-fields p{line-height:1.65}`;document.head.append(style);
 let generation=0;
 const original=window.openItemPage;window.openItemPage=async function(item){original(item);const ticket=++generation;const container=document.querySelector('#dialogbody .item-fields');if(!container)return;
 function add(title,text){const p=document.createElement('p');const b=document.createElement('strong');b.textContent=title+': ';p.append(b,document.createTextNode(text));container.append(p);}
 const allGuides=item.obtaining?.methods|| (item.obtaining?.method?[item.obtaining]:[]);
 if(allGuides.length){for(const guide of allGuides){for(const p of Array.from(container.querySelectorAll('p')))if(p.textContent.includes('Ainda não há um guia'))p.remove();add('Como obter no jogo',guide.method);if(guide.season)add('Estação de cultivo',guide.season);if(Number.isFinite(guide.growthDays)){add('Crescimento inicial',guide.growthDays+' dias, com rega diária');if(guide.regrowDays>0)add('Nova colheita','A cada '+guide.regrowDays+' dias após a primeira colheita');else add('Após colher','É necessário plantar novamente');}}return;}
 if(!Array.from(container.querySelectorAll('p')).some(p=>p.textContent.includes('Ainda não há um guia')))return;
 const pending=document.createElement('p');pending.textContent='Consultando método de obtenção…';container.append(pending);
 try{const title=item.wikiName||item.name;const response=await fetch('/api/wiki?lang=en&title='+encodeURIComponent(title));if(!response.ok)throw Error();const page=await response.json();if(ticket!==generation)return;const doc=new DOMParser().parseFromString(page.html,'text/html');let found=false;for(const row of doc.querySelectorAll('tr')){const cells=row.querySelectorAll(':scope>th,:scope>td');if(cells.length<2)continue;const key=cells[0].textContent.trim();if(/^(source|sources|season|seasons|growth time|grow time|origem|estação|tempo de crescimento)\s*:?$/i.test(key)){add(/^(source|sources|origem)/i.test(key)?'Como obter':/^(season|seasons|estação)/i.test(key)?'Estação':'Tempo de crescimento',cells[1].textContent.trim().replace(/\s+/g,' '));found=true;}}
 if(found){pending.remove();for(const p of Array.from(container.querySelectorAll('p')))if(p.textContent.includes('Ainda não há um guia'))p.remove();}else pending.textContent='Não há informações adicionais de obtenção para este item.';
 }catch{if(ticket===generation)pending.textContent='Não foi possível consultar informações adicionais agora. Os dados locais do jogo continuam disponíveis.';}
 };
})();
(function(){
 const style=document.createElement('style');style.textContent=`.top{display:grid;grid-template-columns:minmax(90px,1fr) minmax(180px,2fr) minmax(230px,1fr);align-items:center;gap:12px;padding:12px 3%}.day-status{grid-column:1;grid-row:1;display:flex;align-items:center;justify-content:center;font-weight:900;color:#50633b}.game-clock{grid-column:2;grid-row:1;justify-content:center;text-align:center;margin:0;font-size:14px}.seasons{grid-column:3;grid-row:1;justify-content:flex-end;margin:0}.brand{align-items:center;gap:12px}.brand>span{display:flex;align-items:center;justify-content:center;flex:none}.brand img{width:38px;height:38px;object-fit:contain;image-rendering:pixelated}@media(max-width:1000px){.top{grid-template-columns:80px 1fr}.seasons{grid-column:1/-1;grid-row:2;justify-content:center}.game-clock{font-size:12px}.brand img{width:30px;height:30px}}`;document.head.append(style);
 const logo=document.querySelector('.brand>span');if(logo){logo.replaceChildren();const img=document.createElement('img');img.alt='Junimo roxo';img.src='https://stardewvalleywiki.com/Special:Redirect/file/Purple_Sleeping_Junimo.png';logo.append(img);}
 function header(data){const top=document.querySelector('.top');let left=top.querySelector('.day-status');if(!left){left=document.createElement('div');left.className='day-status';top.append(left);}left.textContent=data.farm.isNight?'☾ Noite':'☀ Dia';const center=top.querySelector('.game-clock');if(center){const time=data.farm.time||600;const seasons={spring:'Primavera',summer:'Verão',fall:'Outono',winter:'Inverno'};center.textContent=String(Math.floor(time/100)).padStart(2,'0')+':'+String(time%100).padStart(2,'0')+' · '+data.farm.day+' de '+seasons[data.farm.season]+' · Ano '+data.farm.year;}}
 window.addEventListener('guia:update',e=>{header(e.detail);setTimeout(()=>header(e.detail),0);});
 let generation=0;const previous=window.openItemPage;
 window.openItemPage=function(item){previous(item);const ticket=++generation;if(!item.icon?.startsWith('data:image/png;base64,'))return;const img=new Image();img.onload=()=>{if(ticket!==generation)return;try{const canvas=document.createElement('canvas');canvas.width=32;canvas.height=32;const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,0,0,32,32);const pixels=ctx.getImageData(0,0,32,32).data;const buckets=new Map();for(let i=0;i<pixels.length;i+=4){if(pixels[i+3]<128)continue;const [r,g,b]=[pixels[i],pixels[i+1],pixels[i+2]];if(Math.max(r,g,b)-Math.min(r,g,b)<25||Math.max(r,g,b)<55)continue;const key=[r>>5,g>>5,b>>5].join(',');const entry=buckets.get(key)||{count:0,r:0,g:0,b:0};entry.count++;entry.r+=r;entry.g+=g;entry.b+=b;buckets.set(key,entry);}const best=[...buckets.values()].sort((a,b)=>b.count-a.count)[0];if(!best)return;const color=[best.r,best.g,best.b].map(v=>Math.round(v/best.count));const light=color.map(v=>Math.round(v*.2+255*.8));const border=color.map(v=>Math.round(v*.45+80*.55));const modal=document.querySelector('#dialog');modal.style.background='linear-gradient(135deg,rgb('+light.join(',')+'),#fff8e4)';modal.style.borderColor='rgb('+border.join(',')+')';const heading=modal.querySelector('.item-details');if(heading){heading.style.background='rgb('+light.join(',')+')';heading.style.borderColor='rgb('+border.join(',')+')';}}catch(error){console.warn('[Guia] Não foi possível calcular a cor do item:',error.name);}};img.src=item.icon;};
})();
